	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = CapsuleLimit, meta = (ClampMin = "0"))
	float Length = 10.0f;
	void Update(const FCapsuleLimit* Limit)
	{
		UpdateBase(Limit);
		Radius = Limit->Radius;
		Length = Limit->Length;
	}
	FCapsuleLimit Convert() const
	{
		FCapsuleLimit Limit;
		ConvertBase(Limit);
		Limit.Radius = Radius;
		Limit.Length = Length;
		return Limit;
	}
};
