	int num_sequences;
	struct xmp_sequence seq_data[MAX_SEQUENCES];

	char *instrument_path;

	void *extra;			/* format-specific extra fields */

	const struct synth_info *synth;
	void *synth_chip;

	char **scan_cnt;		/* scan counters */
};


