// hash code trait
size_t BlueprintFunction::hashCode() const noexcept
{
    size_t __r = 0;
    __r = __r * 31 + (rd::hash<UClass>()(get_class()));
    __r = __r * 31 + (rd::hash<FString>()(get_name()));
    return __r;
