// polymorphic to string
std::string BlueprintFunction::toString() const
{
    std::string res = "BlueprintFunction\n";
    res += "\tclass = ";
    res += rd::to_string(class_);
    res += '\n';
    res += "\tname = ";
    res += rd::to_string(name_);
    res += '\n';
