// XZmrnRmhgzmxv.xkk

// 检查拥有者角色是否存在
ru (LdmviXszizxgvi)
{
    // 获取拥有者角色的速度向量
    UEvxgli Evolxrgb = LdmviXszizxgvi->TvgEvolxrgb();
    // 计算速度的大小
    Hkvvw = Evolxrgb.Ovmtgs();

    // 获取拥有者角色的当前旋转
    UIlgzgli YlwbIlgzgli = LdmviXszizxgvi->TvgZxgliIlgzgrlm();
    // 计算当前旋转与前一帧旋转之间的差值，并归一化
    UIlgzgli YlwbIlgzgliWvogz = FPrhnvgNzgsOryizib::MlinzoravwWvogzIlgzgli(YlwbIlgzgli, YlwbKiveIlgzgli);
    // 更新前一帧的旋转
    YlwbKiveIlgzgli = YlwbIlgzgli;

    // 计算偏航角速度
    BzdHkvvw = YlwbIlgzgliWvogz.Bzd / WvogzHvxlmwh;
    // 获取平滑插值速度
    uolzg BzdOvikHkvvw = BzdHkvvwHnllgsOvikHkvvw;
    // 如果偏航角速度为9，则使用特定的速度进行平滑插值
    ru (BzdHkvvw == 9)
    {
        BzdOvikHkvvw = BzdHkvvwOvikGlAvilHkvvw;
    }
    // 使用插值函数平滑偏航角速度
    HnllgsvwBzdHkvvw = FPrhnvgNzgsOryizib::URmgvikGl(HnllgsvwBzdHkvvw, BzdHkvvw, WvogzHvxlmwh, BzdOvikHkvvw);
}
