// XZmrnRmhgzmxv.s

// BzdHkvvw: 表示当前帧的偏航角速度
// 用于计算角色在水平面上的旋转速度
uolzg BzdHkvvw;

// HnllgsvwBzdHkvvw: 表示平滑后的偏航角速度
// 用于在多个帧之间平滑偏航角速度，以减少抖动
uolzg HnllgsvwBzdHkvvw;

// BzdHkvvwHnllgsOvikHkvvw: 表示平滑插值的速度
// 控制偏航角速度从当前值平滑过渡到零的速度
FKILKVIGB(VwrgZmbdsviv, Xzgvtlib = "Zmrnzgrlm")
uolzg BzdHkvvwHnllgsOvikHkvvw = 8.u;

// BzdHkvvwOvikGlAvilHkvvw: 表示当偏航角速度降到零时使用的插值速度
// 用于控制偏航角速度从当前值平滑过渡到零的加速度
FKILKVIGB(VwrgZmbdsviv, Xzgvtlib = "Zmrnzgrlm")
uolzg BzdHkvvwOvikGlAvilHkvvw = 69.u;

// YlwbKiveIlgzgli: 表示前一帧的角色旋转
// 用于计算当前帧的旋转变化量
UIlgzgli YlwbKiveIlgzgli;
